const highRiskPhrases = [
  "sole discretion", "without notice", "waives all rights", "non-refundable",
  "indemnify", "hold harmless", "irrevocably", "perpetual", "royalty-free",
  "no liability", "as is", "without limitation", "exclusive property",
  "non-compete", "liquidated damages", "unilaterally"
];

const mediumRiskPhrases = [
  "may terminate", "reasonable satisfaction", "at any time", "confidential",
  "governing law", "amendments", "assign", "third party"
];

return $input.all().map(item => {
  const clauseText = item.json.clause_text;
  const clauseNumber = item.json.clause_number;
  const lowerText = clauseText.toLowerCase();

  const matchedHigh = highRiskPhrases.filter(p => lowerText.includes(p));
  const matchedMedium = mediumRiskPhrases.filter(p => lowerText.includes(p));

  let risk_level = "low";
  let explanation = "No flagged terms found in this clause.";

  if (matchedHigh.length > 0) {
    risk_level = "high";
    explanation = `Contains high-risk terms: ${matchedHigh.join(", ")}`;
  } else if (matchedMedium.length > 0) {
    risk_level = "medium";
    explanation = `Contains terms worth reviewing: ${matchedMedium.join(", ")}`;
  }

  return {
    json: {
      clause_number: clauseNumber,
      clause_text: clauseText,
      risk_level,
      explanation
    }
  };
});

const items = $input.all();
const highRisk = items.filter(i => i.json.risk_level === "high");
const mediumRisk = items.filter(i => i.json.risk_level === "medium");

function clauseRow(i, color) {
  return `
    <div style="border-left: 4px solid ${color}; padding: 10px 15px; margin-bottom: 12px; background:#fafafa;">
      <b>Clause ${i.json.clause_number}</b> — ${i.json.explanation}
      <p style="color:#555; font-size: 13px; margin: 6px 0 0;">"${i.json.clause_text.substring(0, 150)}..."</p>
    </div>`;
}

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; color:#222;">
  <h2 style="border-bottom:2px solid #333; padding-bottom:8px;">📄 Document Review Summary</h2>
  <p><b>Total clauses reviewed:</b> ${items.length}</p>
  <p><b style="color:#c0392b;">High-risk clauses:</b> ${highRisk.length}</p>
  <p><b style="color:#e67e22;">Medium-risk clauses:</b> ${mediumRisk.length}</p>

  ${highRisk.length > 0 ? `<h3 style="color:#c0392b;">🔴 High Risk Clauses</h3>${highRisk.map(i => clauseRow(i, "#c0392b")).join("")}` : ""}

  ${mediumRisk.length > 0 ? `<h3 style="color:#e67e22;">🟠 Medium Risk Clauses</h3>${mediumRisk.map(i => clauseRow(i, "#e67e22")).join("")}` : ""}

  <p style="color:#888; font-size:12px; margin-top:30px;">Generated automatically by your Contract Clause Checker workflow.</p>
</div>
`;

return {
  json: {
    html_body: html,
    high_risk_count: highRisk.length,
    medium_risk_count: mediumRisk.length,
    recipient_email: $('On form submission').first().json['Where should we send your results?']
  }
};

// Get the extracted text from the previous node
const text = $input.first().json.text;

// Split into clauses using numbered patterns (e.g., "1.", "2.", "Section 1", etc.)
// This regex splits on a newline followed by a number and a period, or common section headers
const clauseSplitRegex = /\n(?=\d+\.\s)|\n(?=Section\s+\d+)/gi;

let clauses = text.split(clauseSplitRegex)
  .map(c => c.trim())
  .filter(c => c.length > 20); // filter out tiny fragments/empty lines

// If splitting didn't work well (e.g., only 1 clause found), fall back to splitting by double line breaks
if (clauses.length <= 1) {
  clauses = text.split(/\n\s*\n/)
    .map(c => c.trim())
    .filter(c => c.length > 20);
}

// Return each clause as a separate item so we can loop over them next
return clauses.map((clause, index) => ({
  json: {
    clause_number: index + 1,
    clause_text: clause
  }
}));
